import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>a,mythen:()=>i,stand:()=>n,werk:()=>r}),n=`2026-10-08`,r={titel:`Landkarte der Realität`,fassung:`0.9`,lizenz:`CC BY-NC 4.0`,lizenz_url:`https://creativecommons.org/licenses/by-nc/4.0/deed.de`},i=[{id:`m-flache-erde`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Im Mittelalter glaubten die Gebildeten, die Erde sei eine Scheibe.`,antwort:`falsch`,erklaerung:`Fast alle mittelalterlichen Gelehrten wussten, dass die Erde eine Kugel ist. Der angebliche Scheibenglaube ist eine Legende des 19. Jahrhunderts: Laut Leisman verbreitete sie Washington Irving, und John William Draper und Andrew Dickson White nutzten sie als Beleg für einen Dauerkonflikt zwischen Wissenschaft und Religion. Auch Kolumbus’ Gegner in der königlichen Kommission zweifelten nicht an der Kugelgestalt, sondern hielten den Ozean für zu breit.`,beleg:`Garwood, C. (2008): Flat Earth: The History of an Infamous Idea. Leisman, G. (2019): The World is not Flat. Russell, J. B. (1991): Inventing the Flat Earth: Columbus and Modern Historians. New York: Praeger, S. 8–9. Cormack, L. B. (2009): Myth 3. That Medieval Christians Taught That the Earth Was Flat, in: Numbers, R. L. (Hg.): Galileo Goes to Jail and Other Myths about Science and Religion. Cambridge, MA: Harvard University Press, S. 28–34.`,buch:`Landkarte der Realität, Buch 2, Werkstück F.4.2 (Religionen) und D.3.8 (Galileo-Gambit)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Fast alle Gelehrten des Mittelalters wussten, dass die Erde eine Kugel ist. Die Erzählung vom mittelalterlichen Scheibenglauben ist eine Legende des 19. Jahrhunderts, die einen Dauerkonflikt zwischen Wissenschaft und Religion belegen sollte.`,prueffrage:`Was schrieben mittelalterliche Gelehrte selbst über die Gestalt der Erde?`,quellen:[{typ:`url`,kurz:`Russell, J. B. (1997): The Myth of the Flat Earth. American Scientific Affiliation (Vortrag/Essay)`,oeffentlich:!0,url:`https://www.asa3.org/ASA/topics/history/1997Russell.html`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Russell, J. B. (1991): Inventing the Flat Earth: Columbus and Modern Historians. New York: Praeger`,oeffentlich:!1,seite:`8–9`},{typ:`literatur`,kurz:`Leisman, G. (2019): The World is not Flat`,oeffentlich:!1,seite:`PDF-S. 3`}]},{id:`m-sokrates`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Sokrates sagte: „Ich weiß, dass ich nichts weiß.“`,antwort:`differenziert`,erklaerung:`In Platons Apologie sagt Sokrates vorsichtiger, er glaube nicht zu wissen, was er nicht weiß. Die zugespitzte Formel ist eine spätere Verkürzung.`,beleg:`Platon: Apologie des Sokrates, 21d.`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Der Gedanke ist echt, die Formel nicht: In Platons Apologie sagt Sokrates vorsichtiger, er glaube nicht zu wissen, was er nicht weiß. Der knappe Satz „Ich weiß, dass ich nichts weiß“ ist eine spätere Verkürzung.`,prueffrage:`In welchem antiken Text soll Sokrates das gesagt haben, und wie lautet die Stelle dort?`,quellen:[{typ:`url`,kurz:`Platon: Apologie 21d, engl. Übers. H. N. Fowler (Perseus Digital Library)`,oeffentlich:!0,url:`https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0170%3Atext%3DApol.%3Asection%3D21d`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Farnsworth, W. (2023): Die sokratische Methode. FinanzBuch Verlag, Kap. 16 „Sokrates und die Skeptiker“`,oeffentlich:!1,seite:`PDF-S. 400`}]},{id:`m-ockham`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Die berühmte Formel „Entia non sunt multiplicanda praeter necessitatem“ stammt von Wilhelm von Ockham.`,antwort:`falsch`,erklaerung:`Ockham selbst schrieb unter anderem „Numquam ponenda est pluralitas sine necessitate“. Die bekannte Fassung stammt nicht von ihm, sondern aus dem 17. Jahrhundert: der Sache nach 1639 bei dem Scotisten John Punch, in der heutigen Wortfolge 1654 bei Johannes Clauberg. Den englischen Namen „Occam’s Razor“ gibt es erst seit 1852.`,beleg:`Thorburn, W. M. (1918): The Myth of Occam’s Razor. Mind 27(3), S. 345–353, hier S. 347–352. https://doi.org/10.1093/mind/XXVII.3.345`,buch:`Landkarte der Realität, Buch 2, Werkstück A.1.1 (Ockhams Rasiermesser)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Den Grundgedanken formulierte Ockham selbst, etwa als „Numquam ponenda est pluralitas sine necessitate“. Die berühmte Formel mit den „entia“ stammt aber erst aus dem 17. Jahrhundert und nicht von ihm.`,prueffrage:`Welche Schrift Ockhams wird für die Formel angegeben, und hat jemand den Wortlaut dort nachgeschlagen?`,quellen:[{typ:`url`,kurz:`Thorburn, W. M. (1918): The Myth of Occam’s Razor. Mind 27(107), S. 345–353 (Transkription Wikisource)`,oeffentlich:!0,doi:`10.1093/mind/XXVII.3.345`,url:`https://en.wikisource.org/wiki/The_Myth_of_Occam%27s_Razor`,seite:`350–352`,abruf:`2026-10-12`},{typ:`url`,kurz:`Stanford Encyclopedia of Philosophy: William of Ockham`,oeffentlich:!0,url:`https://plato.stanford.edu/entries/ockham/`,abruf:`2026-10-12`}]},{id:`m-maslow`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Abraham Maslow hat die berühmte Bedürfnis-Pyramide gezeichnet.`,antwort:`falsch`,erklaerung:`Maslow beschrieb 1943 eine Theorie der Motivation, stellte seine Hierarchie aber nie als Diagramm dar. Die wohl erste Pyramide erschien 1960 bei dem Berater Charles McDermid in der Managementliteratur. Weltweite Daten aus 123 Ländern zeigen zudem nur eine grobe Reihenfolge, keine strikte Stufenfolge der Bedürfnisse.`,beleg:`Maslow, A. H. (1943): A Theory of Human Motivation. Psychological Review 50(4), S. 370–396. Tay, L.; Diener, E. (2011): Needs and Subjective Well-Being Around the World. Journal of Personality and Social Psychology 101(2), S. 354–365, hier S. 354, 361 und 363. https://doi.org/10.1037/a0023779. Bridgman, T.; Cummings, S.; Ballard, J. (2019): Who Built Maslow’s Pyramid? Academy of Management Learning & Education 18(1), S. 81–98, hier S. 83 und 87. https://doi.org/10.5465/amle.2017.0351`,buch:`Landkarte der Realität, Buch 1, Band III, Sektion III.2.3 (Der Kompass und der Motor)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Maslow beschrieb 1943 eine Rangfolge menschlicher Bedürfnisse, zeichnete sie aber nie als Pyramide. Die bekannte Grafik kam um 1960 aus der Managementliteratur; weltweite Daten zeigen zudem nur eine grobe, keine strikte Stufenfolge.`,prueffrage:`Wo ist die Pyramide zum ersten Mal abgebildet, und stammt diese Abbildung aus Maslows eigenen Veröffentlichungen?`,quellen:[{typ:`doi`,kurz:`Bridgman, T.; Cummings, S.; Ballard, J. (2019): Who Built Maslow’s Pyramid? Academy of Management Learning & Education 18(1), S. 81–98`,oeffentlich:!1,doi:`10.5465/amle.2017.0351`,seite:`83, 87`},{typ:`doi`,kurz:`Tay, L.; Diener, E. (2011): Needs and Subjective Well-Being Around the World. Journal of Personality and Social Psychology 101(2), S. 354–365`,oeffentlich:!1,doi:`10.1037/a0023779`,seite:`354, 361`},{typ:`url`,kurz:`Kaufman, S. B. (2019): Who Created Maslow’s Iconic Pyramid? Scientific American (Blog Beautiful Minds)`,oeffentlich:!0,url:`https://www.scientificamerican.com/blog/beautiful-minds/who-created-maslows-iconic-pyramid`,abruf:`2026-10-12`}]},{id:`m-kokosnuss`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Herabfallende Kokosnüsse töten weltweit jedes Jahr rund 150 Menschen, mehr als Haie.`,antwort:`falsch`,erklaerung:`Die Zahl stammt aus einer Pressemitteilung eines Reiseversicherers (2002) und wird ohne Primärquelle weiterverbreitet. Die einzige zugrunde liegende Studie wertete vier Jahre Unfallaufnahmen eines einzigen Krankenhauses in Papua-Neuguinea aus: vor allem Verletzungen, erwähnt werden zwei Menschen, die im Dorf sofort starben. Eine weltweite Zahl lässt sich daraus nicht ableiten.`,beleg:`Barss, P. (1984): Injuries Due to Falling Coconuts. Journal of Trauma 24(11), S. 990–991.`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.7.3 (Die Verfügbarkeitsheuristik)`,familie:`zahl-zur-quelle`,fertigkeit:`F1`,stufe:2,kurz:`Die Zahl von rund 150 Toten geht auf eine Pressemitteilung eines Reiseversicherers zurück. Die einzige Studie dazu betrifft ein einzelnes Krankenhaus in Papua-Neuguinea; eine weltweite Todeszahl lässt sich daraus nicht ableiten.`,prueffrage:`Wer hat die Todesfälle durch Kokosnüsse weltweit gezählt, und auf welche Erhebung stützt sich die Zahl?`,quellen:[{typ:`url`,kurz:`Adams, C.: Are 150 people killed each year by falling coconuts? The Straight Dope`,oeffentlich:!0,url:`https://www.straightdope.com/21343538/are-150-people-killed-each-year-by-falling-coconuts`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Barss, P. (1984): Injuries Due to Falling Coconuts. Journal of Trauma 24(11), S. 990–991`,oeffentlich:!1,doi:`10.1097/00005373-198411000-00012`}]},{id:`m-banane`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Der Mensch stimmt zu 50 % mit der Banane überein.`,antwort:`falsch`,erklaerung:`Viele unserer Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Das heißt nicht, dass unser Erbgut zur Hälfte übereinstimmt. Beim Schimpansen liegt die Übereinstimmung der vergleichbaren Sequenzen bei rund 99 %.`,beleg:`The Naked Scientists (2018): Mythconception: We share half our DNA with bananas. https://www.thenakedscientists.com/articles/interviews/mythconception-we-share-half-our-dna-bananas. Chimpanzee Sequencing and Analysis Consortium (2005): Initial sequence of the chimpanzee genome and comparison with the human genome. Nature 437, S. 69–87.`,buch:`Landkarte der Realität, Buch 2, Werkstück C.3.1 (DNA, Gene & Vererbung)`,familie:`zahl-zur-quelle`,fertigkeit:`F1`,stufe:2,kurz:`Viele menschliche Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt nicht, dass unser Erbgut zur Hälfte mit dem der Banane übereinstimmt.`,prueffrage:`Welche Messung steckt hinter den 50 %, und was genau wurde dabei mit was verglichen?`,quellen:[{typ:`url`,kurz:`National Human Genome Research Institute (2005): New Genome Comparison Finds Chimps, Humans Very Similar at the DNA Level (Pressemitteilung, 31.08.2005)`,oeffentlich:!0,url:`https://www.genome.gov/15515096/2005-release-new-genome-comparison-finds-chimps-humans-very-similar-at-dna-level`,abruf:`2026-10-12`},{typ:`url`,kurz:`The Naked Scientists (2018): Mythconception: We share half our DNA with bananas (L. Thomson, Univ. Cambridge)`,oeffentlich:!0,url:`https://www.thenakedscientists.com/articles/interviews/mythconception-we-share-half-our-dna-bananas`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Chimpanzee Sequencing and Analysis Consortium (2005): Initial sequence of the chimpanzee genome and comparison with the human genome. Nature 437, S. 69–87`,oeffentlich:!1,doi:`10.1038/nature04072`,seite:`69`}]},{id:`m-yellowstone`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Seit die Wölfe 1995 in den Yellowstone zurückkehrten, haben die Flüsse dort ihren Lauf geändert.`,antwort:`differenziert`,erklaerung:`Dass die Rückkehr der Wölfe Folgen im Ökosystem hatte, nehmen viele Fachleute an; wie stark diese Kaskade ist, ist umstritten. Eine Nachuntersuchung zeigt, dass die Auswahl der Messstellen das Lehrbuchbeispiel übertrieben hat. Die These, die Flüsse hätten ihren Lauf geändert, geht auf einzelne Fachaufsätze zurück, wurde durch populäre Darstellungen zugespitzt und gilt vielen Fachleuten als deutlich überzeichnet. Am Rückgang der Hirsche hatten auch Jagd, Dürrejahre, Bären und Pumas ihren Anteil.`,beleg:`Ripple, W. J.; Beschta, R. L. (2012): Trophic cascades in Yellowstone: The first 15 years after wolf reintroduction. Biological Conservation 145(1), S. 205–213. https://doi.org/10.1016/j.biocon.2011.11.005. Brice, E. M.; Larsen, E. J.; MacNulty, D. R. (2022): Sampling bias exaggerates a textbook example of a trophic cascade. Ecology Letters 25(1), S. 177–188. https://doi.org/10.1111/ele.13915`,buch:`Landkarte der Realität, Buch 2, Werkstück A.6 (Systemdenken)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Die Rückkehr der Wölfe hatte im Yellowstone nach Ansicht vieler Fachleute Folgen für das Ökosystem, deren Ausmaß umstritten ist. Dass sie die Flüsse umgelenkt habe, gilt als deutlich überzeichnet; am Rückgang der Hirsche wirkten auch Jagd, Dürre, Bären und Pumas mit.`,prueffrage:`Wer hat die Flussläufe vor und nach 1995 vermessen, und was änderte sich in dieser Zeit sonst noch im Park?`,quellen:[{typ:`doi`,kurz:`Brice, E. M.; Larsen, E. J.; MacNulty, D. R. (2022): Sampling bias exaggerates a textbook example of a trophic cascade. Ecology Letters 25(1), S. 177–188`,oeffentlich:!0,doi:`10.1111/ele.13915`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9298920/`,abruf:`2026-10-12`},{typ:`url`,kurz:`National Park Service: Elk – Yellowstone National Park`,oeffentlich:!0,url:`https://www.nps.gov/yell/learn/nature/elk.htm`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Ripple, W. J.; Beschta, R. L. (2012): Trophic cascades in Yellowstone: The first 15 years after wolf reintroduction. Biological Conservation 145(1), S. 205–213`,oeffentlich:!1,doi:`10.1016/j.biocon.2011.11.005`}]},{id:`m-frosch`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Ein Frosch bleibt in langsam erhitztem Wasser sitzen, bis er gekocht ist.`,antwort:`falsch`,erklaerung:`Ein Frosch springt heraus, sobald ihm das Wasser zu warm wird. Die Legende geht auf widersprüchliche Versuche des 19. Jahrhunderts zurück, teils an Fröschen ohne Großhirn.`,beleg:`Gibbons, W. (2002): The Legend of the Boiling Frog Is Just a Legend. Ecoviews, Savannah River Ecology Laboratory. Fallows, J. (2006): The Boiled-Frog Myth: Stop the Lying Now! The Atlantic.`,buch:`Landkarte der Realität, Buch 2, Anhang IV.2, Akte #11 (Der Frosch im Kochtopf)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:1,kurz:`Ein Frosch springt aus dem Wasser, sobald es ihm zu warm wird. Die Legende geht auf widersprüchliche Versuche des 19. Jahrhunderts zurück, teils an Fröschen, denen das Großhirn fehlte.`,prueffrage:`Wer hat den Versuch tatsächlich durchgeführt, und unter welchen Bedingungen?`,quellen:[{typ:`url`,kurz:`Gibbons, W. (2002): The Legend of the Boiling Frog Is Just a Legend. Ecoviews, Savannah River Ecology Laboratory, 18.11.2002 (Wayback-Kopie)`,oeffentlich:!0,url:`https://web.archive.org/web/20140925033215/http://srel.uga.edu:80/outreach/ecoviews/ecoview021118.htm`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Heinzmann, A. (1872): Ueber die Wirkung sehr allmäliger Aenderungen thermischer Reize auf die Empfindungsnerven. Pflügers Archiv 6, S. 222–236`,oeffentlich:!0,doi:`10.1007/BF01612252`,url:`https://zenodo.org/record/2397982`,abruf:`2026-10-12`},{typ:`url`,kurz:`Wikipedia: Boiling frog (Abschnitt zu den Versuchen des 19. Jahrhunderts)`,oeffentlich:!0,url:`https://en.wikipedia.org/wiki/Boiling_frog`,abruf:`2026-10-12`}]},{id:`m-kobra`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Die Geschichte vom „Kobra-Effekt“ ist gut belegt: Auf Kobras wurde ein Kopfgeld ausgesetzt, also züchteten Leute im britischen Indien Kobras.`,antwort:`falsch`,erklaerung:`Die heutige Form der Geschichte stammt vom Ökonomen Horst Siebert (2001). Eine Untersuchung der Friends of Snakes Society (2025) fand keine zeitgenössischen Belege für Kobra-Zuchtbetriebe oder Strafverfahren im britischen Indien. Nach ihrer Darstellung führt die Spur zu einem Zeitungsbericht von 1873, der den Vorwurf nur als Gerücht wiedergab, und die Bombay Natural History Society hielt eine Zucht 1887 auf Anfrage der Regierung für „höchst unwahrscheinlich“. Das Programm in Madras wurde demnach 1873 aus Kostengründen eingeschränkt, nicht wegen aufgedeckten Betrugs. Der Mechanismus dahinter, der Fehlanreiz, bleibt real.`,beleg:`Siebert, H. (2001): Der Kobra-Effekt. Friends of Snakes Society (2025): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory. https://friendsofsnakes.org.in/cobra-effect/ (abgerufen 6.10.2026).`,buch:`Landkarte der Realität, Buch 2, Werkstück A.8 (Denken zweiter und dritter Ordnung)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Dass Kopfgelder Fehlanreize setzen können, ist real. Für Kobra-Zuchtbetriebe im britischen Indien fehlen aber zeitgenössische Belege; eine Untersuchung von 2025 führt die Spur auf ein Gerücht von 1873 zurück, die heutige Fassung der Geschichte stammt von 2001.`,prueffrage:`Welche Quellen aus der Kolonialzeit selbst werden für die Kobra-Zucht genannt?`,quellen:[{typ:`url`,kurz:`Friends of Snakes Society (2025): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory`,oeffentlich:!0,url:`https://friendsofsnakes.org.in/cobra-effect/`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Siebert, H. (2001): Der Kobra-Effekt. Wie man Irrwege der Wirtschaftspolitik vermeidet`,oeffentlich:!1}]},{id:`m-houdini`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Houdini und James Randi trafen sich und entlarvten gemeinsam falsche Medien.`,antwort:`falsch`,erklaerung:`Houdini starb 1926, Randi wurde erst 1928 geboren. Real sind Houdinis Kampagne gegen betrügerische Medien und Randis spätere Selbstverortung als Houdinis Nachfolger.`,beleg:`Randi, J.; Sugar, B. (1976): Houdini: His Life and Art.`,buch:`Landkarte der Realität, Buch 2, Werkstück A.18 (Wissenschaftlicher Skeptizismus)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:2,kurz:`Ein Treffen war unmöglich: Houdini starb 1926, Randi wurde erst 1928 geboren. Real sind Houdinis Kampagne gegen betrügerische Medien und Randis spätere Selbstverortung als sein Nachfolger.`,prueffrage:`Welcher Bericht beschreibt dieses Treffen, und von wann stammt er?`,quellen:[{typ:`doi`,kurz:`Ball, P. (2020): James Randi (1928–2020). Nature 587, S. 34 (Nachruf)`,oeffentlich:!0,doi:`10.1038/d41586-020-03050-5`,url:`https://media.nature.com/original/magazine-assets/d41586-020-03050-5/d41586-020-03050-5.pdf`,abruf:`2026-10-12`},{typ:`url`,kurz:`Library of Congress, Inside Adams (2014): Harry Houdini’s Rare Magic Books (E. Gettins)`,oeffentlich:!0,url:`https://blogs.loc.gov/inside_adams/2014/10/harry-houdinis-rare-magic-books/`,abruf:`2026-10-12`},{typ:`url`,kurz:`Wikipedia: James Randi`,oeffentlich:!0,url:`https://en.wikipedia.org/wiki/James_Randi`,abruf:`2026-10-12`}]},{id:`m-genovese`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Kitty Genovese wurde 1964 ermordet, während 38 Nachbarn zusahen und nichts taten.`,antwort:`falsch`,erklaerung:`Das Bild stammt aus einem Zeitungsbericht von 1964 (Überschrift 37, Text 38 Zeugen). Gerichtsakten und Zeugenaussagen zeichnen ein anderes Bild. Die New York Times räumte die Fehler 2016 selbst ein.`,beleg:`Manning, R.; Levine, M.; Collins, A. (2007): The Kitty Genovese Murder and the Social Psychology of Helping: The Parable of the 38 Witnesses. American Psychologist 62(6), S. 555–562.`,buch:`Landkarte der Realität, Buch 2, Werkstück E.2.3 (Das Schweigen der Zeugen)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Kitty Genovese wurde 1964 ermordet, doch das Bild von 38 tatenlos zusehenden Nachbarn stammt aus einem Zeitungsbericht. Gerichtsakten und Zeugenaussagen zeichnen ein anderes Bild; die New York Times räumte die Fehler 2016 selbst ein.`,prueffrage:`Woher stammt die Zahl 38, und was sagen Gerichtsakten und Zeugenaussagen zum Hergang?`,quellen:[{typ:`doi`,kurz:`Manning, R.; Levine, M.; Collins, A. (2007): The Kitty Genovese Murder and the Social Psychology of Helping: The Parable of the 38 Witnesses. American Psychologist 62(6), S. 555–562`,oeffentlich:!1,doi:`10.1037/0003-066X.62.6.555`},{typ:`url`,kurz:`Jarrett, C. (2007): The truth behind the story of Kitty Genovese and the bystander effect. BPS Research Digest`,oeffentlich:!0,url:`https://bps.org.uk/research-digest/truth-behind-story-kitty-genovese-and-bystander-effect`,abruf:`2026-10-12`},{typ:`url`,kurz:`Singal, J. (2016): How the false story of Kitty Genovese’s murder went viral. SBS The Feed (zitiert den NYT-Nachruf auf Moseley)`,oeffentlich:!0,url:`https://www.sbs.com.au/news/the-feed/article/how-the-false-story-of-kitty-genoveses-murder-went-viral/ud7v63ngq`,abruf:`2026-10-12`}]},{id:`m-stanford`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Im Stanford-Prison-Experiment wurden die Wärter ganz von selbst zu Sadisten.`,antwort:`falsch`,erklaerung:`Die Auswertung von Zimbardos eigenem Archiv zeigt, dass der Aufseher David Jaffe die Wärter in Tonaufnahmen ausdrücklich zu mehr Härte anhielt. Zimbardo bestreitet Teile der Kritik.`,beleg:`Le Texier, T. (2019): Debunking the Stanford Prison Experiment. American Psychologist 74(7), S. 823–839.`,buch:`Landkarte der Realität, Buch 2, Werkstück E.2.7 (Macht)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Die Wärter wurden nicht ganz von selbst hart: Tonaufnahmen aus Zimbardos eigenem Archiv zeigen, dass der Aufseher David Jaffe sie ausdrücklich zu mehr Härte anhielt. Zimbardo bestreitet Teile dieser Kritik.`,prueffrage:`Welche Anweisungen erhielten die Wärter während des Versuchs, und wer hat die Archivunterlagen ausgewertet?`,quellen:[{typ:`doi`,kurz:`Le Texier, T. (2019): Debunking the Stanford Prison Experiment. American Psychologist 74(7), S. 823–839`,oeffentlich:!0,doi:`10.1037/amp0000401`,url:`https://www.gwern.net/doc/psychology/2019-letexier.pdf`,seite:`PDF-S. 7 (Online-First-Fassung)`,abruf:`2026-10-12`},{typ:`url`,kurz:`Zimbardo, P. (2018): Philip Zimbardo’s Response to Recent Criticisms of the Stanford Prison Experiment. prisonexp.org`,oeffentlich:!0,url:`https://www.prisonexp.org/response`,abruf:`2026-10-12`}]},{id:`m-semmelweis`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Ignaz Semmelweis wurde als verrückt erklärt und starb Jahre später in der Anstalt.`,antwort:`differenziert`,erklaerung:`Die geglättete Fassung verkürzt den Hergang: 1865 wurde Semmelweis unter einem Vorwand in eine Wiener Anstalt gelockt, versuchte zu fliehen und wurde dabei von Wärtern schwer misshandelt. Er starb nicht nach Jahren in der Anstalt, sondern vierzehn Tage nach der Einweisung an einer Blutvergiftung, ausgehend von offenen Wunden, die vermutlich von der Misshandlung stammten. Was seinen vorangegangenen geistigen Verfall auslöste, ist ungeklärt.`,beleg:`Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), S. 293–302, hier S. 298. https://doi.org/10.1007/s10354-020-00738-1`,buch:`Landkarte der Realität, Buch 2, Werkstück A.20 (Paradigma & Paradigmenwechsel)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Semmelweis kam 1865 tatsächlich in eine Wiener Anstalt, wurde aber unter einem Vorwand dorthin gelockt, misshandelt und starb schon vierzehn Tage später an einer Blutvergiftung, nicht erst nach Jahren.`,prueffrage:`Was berichten Akten und Biografien über Einweisung, Aufenthalt und Todesursache?`,quellen:[{typ:`doi`,kurz:`Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), S. 293–302`,oeffentlich:!0,doi:`10.1007/s10354-020-00738-1`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC7476981/`,seite:`298`,abruf:`2026-10-12`}]},{id:`m-system1`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`„System 1“ steuert 95 % unseres Denkens.`,antwort:`falsch`,erklaerung:`Die Zahl (mal 95, mal 90 oder 98 %) stammt aus dem Neuromarketing und lässt sich auf keine belastbare Studie zurückführen. Kahneman beziffert den Anteil nirgends und nennt die beiden Systeme ausdrücklich nützliche Fiktionen.`,beleg:`Kahneman, D. (2011): Thinking, Fast and Slow. New York: Farrar, Straus and Giroux, Teil I, Kapitel 1. Zur Herkunft der Zahl: Mahoney, M. (2003): The Subconscious Mind of the Consumer (And How To Reach It). Interview mit Gerald Zaltman, Harvard Business School Working Knowledge, 13.01.2003; Harvey, C. (2025): 3 dangerous behavioural science myths – and what to do about them. Research World (ESOMAR), 15.05.2025.`,buch:`Landkarte der Realität, Buch 2, Werkstück E.1.1 (System 1 & System 2)`,familie:`zahl-zur-quelle`,fertigkeit:`F1`,stufe:2,kurz:`Die Zahl schwankt zwischen 90, 95 und 98 % und stammt aus dem Neuromarketing, ohne belastbare Studie dahinter. Kahneman nennt keinen Anteil und bezeichnet die beiden Systeme selbst als nützliche Fiktionen.`,prueffrage:`Welche Studie hat diesen Anteil gemessen, und mit welcher Methode?`,quellen:[{typ:`url`,kurz:`Harvey, C. (2025): 3 dangerous behavioural science myths – and what to do about them. Research World (ESOMAR), 15.05.2025`,oeffentlich:!0,url:`https://researchworld.com/articles/3-dangerous-behavioural-science-myths-and-what-to-do-about-them`,abruf:`2026-10-12`},{typ:`url`,kurz:`Harvard Business School Working Knowledge: Mahoney, M. (2003): The Subconscious Mind of the Consumer (And How To Reach It). Interview mit Gerald Zaltman, 13.01.2003`,oeffentlich:!0,url:`https://www.library.hbs.edu/working-knowledge/the-subconscious-mind-of-the-consumer-and-how-to-reach-it`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Kahneman, D. (2011): Thinking, Fast and Slow. New York: Farrar, Straus and Giroux, Teil I, Kap. 1, Abschnitt „Useful Fictions“ (dt. Schnelles Denken, langsames Denken, 2012, Abschnitt „Nützliche Fiktionen“)`,oeffentlich:!1}]},{id:`m-goodhart`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Charles Goodhart formulierte: „Wenn ein Maß zum Ziel wird, hört es auf, ein gutes Maß zu sein.“`,antwort:`differenziert`,erklaerung:`Goodhart schrieb 1975 sinngemäß, statistische Regelmäßigkeiten brächen zusammen, sobald man sie zur Steuerung nutzt. Die griffige Fassung wurde ihm erst 1997 von der Anthropologin Marilyn Strathern in dieser Zuspitzung zugeschrieben.`,beleg:`Goodhart, C. A. E. (1975): Problems of Monetary Management: The U.K. Experience. Zuerst in: Reserve Bank of Australia, Papers in Monetary Economics, Bd. I (1976); Nachdruck in: Goodhart, Monetary Theory and Practice, London: Macmillan 1984, S. 91–121. Strathern, M. (1997): „Improving ratings“: audit in the British University system. European Review 5(3), S. 305–321.`,buch:`Landkarte der Realität, Buch 2, Anhang V.1 (Die Geschichte der Aufklärung)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Der Gedanke geht auf Goodhart zurück: Er schrieb 1975 sinngemäß, statistische Regelmäßigkeiten brächen zusammen, sobald man sie zur Steuerung nutzt. Die griffige Fassung mit Maß und Ziel stammt erst von der Anthropologin Marilyn Strathern (1997).`,prueffrage:`Wie lautet die Stelle in Goodharts eigenem Text von 1975?`,quellen:[{typ:`url`,kurz:`FORRT – Framework for Open and Reproducible Research Training: Glossary, „Goodhart’s Law“`,oeffentlich:!0,url:`https://forrt.org/glossary/english/goodhart_s_law/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Strathern, M. (1997): ‘Improving ratings’: audit in the British University system. European Review 5(3), S. 305–321`,oeffentlich:!1,doi:`10.1002/(SICI)1234-981X(199707)5:3<305::AID-EURO184>3.0.CO;2-4`},{typ:`doi`,kurz:`Goodhart, C. A. E. (1975): Problems of Monetary Management: The U.K. Experience. Zuerst in: Reserve Bank of Australia, Papers in Monetary Economics, Bd. I (1976); Nachdruck in: Goodhart, Monetary Theory and Practice, London: Macmillan 1984, S. 91–121`,oeffentlich:!1,doi:`10.1007/978-1-349-17295-5_4`}]},{id:`m-birds`,typ:`mythos`,status:`entwurf`,thema:`Netz und Medien`,aussage:`Die Bewegung „Birds Aren’t Real“ war von Anfang an ernst gemeint.`,antwort:`falsch`,erklaerung:`Der Gründer räumte 2021 gegenüber der New York Times ein, dass die Bewegung von Anfang an Satire war. Ironie und Überzeugung lassen sich im Netz schwer trennen (Poes Gesetz).`,beleg:`Lorenz, T. (2021): Birds Aren’t Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 9. Dezember 2021.`,buch:`Landkarte der Realität, Buch 2, Werkstück B.22 (Poes Gesetz)`,familie:`satire-oder-ernst`,fertigkeit:`F1`,stufe:1,kurz:`Die Bewegung war Satire: Ihr Gründer räumte 2021 gegenüber der New York Times ein, dass sie von Anfang an so gemeint war. Im Netz lassen sich Ironie und echte Überzeugung schwer unterscheiden.`,prueffrage:`Was sagen die Gründer selbst über ihre Absicht, und seit wann?`,quellen:[{typ:`url`,kurz:`Thompson, S. (2021): Fact Check: 'Birds Aren't Real' Is NOT A Real Conspiracy -- It's A Parody Social Movement. Lead Stories, 14.12.2021`,oeffentlich:!0,url:`https://leadstories.com/hoax-alert/2021/12/fact-check-birds-arent-real-is-not-a-real-conspiracy-its-a-parody-social-movement.html`,abruf:`2026-10-12`},{typ:`url`,kurz:`TED Audio Collective: Do we have something to learn from conspiracy theories? (w/ Peter McIndoe). Podcast How to Be a Better Human, 24.07.2023, Transkript`,oeffentlich:!0,url:`https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Lorenz, T. (2021): Birds Aren’t Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 09.12.2021`,oeffentlich:!1}]},{id:`m-advocatus`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Seit der Reform von 1983 gibt es den „Advocatus Diaboli“ im Heiligsprechungsverfahren nicht mehr.`,antwort:`falsch`,erklaerung:`Die Reform schaffte das Amt nicht ab, sondern entmachtete es: kein Vetorecht mehr und kein Auftrag, aktiv nach Einwänden zu suchen. Wie stark das die Zahl der Heiligsprechungen beeinflusste, ist unter Kirchenhistorikern umstritten.`,beleg:`Johannes Paul II.: Apostolische Konstitution Divinus Perfectionis Magister, 25. Januar 1983, Nr. 10 und 13.`,buch:`Landkarte der Realität, Buch 2, Werkstück A.11 (Advocatus Diaboli)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Die Reform von 1983 schaffte das Amt des Advocatus Diaboli nicht ab, nahm ihm aber das Vetorecht und den Auftrag, aktiv nach Einwänden zu suchen. Wie stark das die Zahl der Heiligsprechungen beeinflusste, ist umstritten.`,prueffrage:`Was legt der Text der Reform von 1983 selbst über dieses Amt fest, und wo lässt er sich nachlesen?`,quellen:[{typ:`url`,kurz:`Johannes Paul II. (1983): Apostolische Konstitution Divinus Perfectionis Magister, 25.01.1983, engl. Übersetzung, vatican.va, Nr. 10 und 13`,oeffentlich:!0,url:`https://www.vatican.va/content/john-paul-ii/en/apost_constitutions/documents/hf_jp-ii_apc_25011983_divinus-perfectionis-magister.html`,abruf:`2026-10-12`}]},{id:`m-mcnamara`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Die vierstufige Formel des „McNamara-Fehlschlusses“ (nur messen, was sich leicht messen lässt) stammt von Robert McNamara selbst.`,antwort:`falsch`,erklaerung:`Die Formel prägte Daniel Yankelovich 1971 in einer Rede und gab ihr dort auch den Namen „McNamara fallacy“, ausdrücklich ohne McNamara herabsetzen zu wollen. Weit verbreitet hat sie später unter anderem Charles Handy (1994). Die Kritik am „Body Count“ im Vietnamkrieg bleibt davon unberührt.`,beleg:`Yankelovich, D. (1971): The New Odds. Rede vom 15. Oktober 1971. Handy, C. (1994): The Empty Raincoat. London: Hutchinson, S. 219.`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.8 (Die Kunst, mit Zahlen zu lügen)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Die vierstufige Formel stammt nicht von McNamara, sondern von Daniel Yankelovich (1971); weit verbreitet hat sie später unter anderem Charles Handy. Die Kritik am „Body Count“ im Vietnamkrieg bleibt davon unberührt.`,prueffrage:`In welchem Text taucht die Formel zum ersten Mal auf, und wer spricht sie dort aus?`,quellen:[{typ:`url`,kurz:`Wikipedia (engl.): McNamara fallacy`,oeffentlich:!0,url:`https://en.wikipedia.org/wiki/McNamara_fallacy`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Yankelovich, D. (1971): The New Odds. Rede vor der Eleventh Annual Marketing Strategy Conference des Sales Executives Club of New York, 15.10.1971, Typoskript (Daniel Yankelovich Papers, UC San Diego Special Collections; Calibre sachbuch:9261)`,oeffentlich:!1,seite:`PDF-S. 2 und 5`},{typ:`literatur`,kurz:`Handy, C. (1994): The Empty Raincoat: Making Sense of the Future. London: Hutchinson`,oeffentlich:!1}]},{id:`m-gaslight`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Der Begriff „Gaslighting“ geht auf ein Theaterstück von 1938 zurück.`,antwort:`wahr`,erklaerung:`Patrick Hamiltons Stück „Gas Light“ wurde am 5. Dezember 1938 in London uraufgeführt. Ein Ehemann sucht nachts heimlich in der Wohnung darüber nach versteckten Juwelen; weil er dort die Gaslampen anzündet, wird das Licht im übrigen Haus schwächer, und er redet seiner Frau ein, sie bilde sich die Veränderung nur ein. Verfilmungen folgten 1940 und 1944.`,beleg:`Hamilton, P. (1938): Gas Light. Uraufführung am 5. Dezember 1938, Richmond Theatre, London.`,buch:`Landkarte der Realität, Buch 2, Werkstück D.3.3 (Gaslighting)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:2,kurz:`Der Begriff geht auf Patrick Hamiltons Stück „Gas Light“ zurück, 1938 in London uraufgeführt: Ein Ehemann redet seiner Frau ein, sie bilde sich das schwächer werdende Gaslicht nur ein. Verfilmungen folgten 1940 und 1944.`,prueffrage:`Wo ist der Begriff zuerst belegt, und lässt sich das Datum dieser Quelle unabhängig nachprüfen?`,quellen:[{typ:`url`,kurz:`Wikipedia (engl.): Gas Light`,oeffentlich:!0,url:`https://en.wikipedia.org/wiki/Gas_Light`,abruf:`2026-10-12`},{typ:`url`,kurz:`Gutoskey, E. (2022): The Forgotten Hollywood History Behind the Term Gaslighting. Mental Floss, 28.01.2022`,oeffentlich:!0,url:`https://www.mentalfloss.com/language/words/forgotten-hollywood-history-behind-term-gaslighting`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Hamilton, P. (1938): Gas Light. Theaterstück, Uraufführung Richmond Theatre, London`,oeffentlich:!1}]},{id:`m-chemtrails`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Fachleute für Atmosphärenforschung haben Belege für ein geheimes, großflächiges Sprühprogramm gefunden.`,antwort:`falsch`,erklaerung:`In einer Befragung von 77 Fachleuten der Atmosphären- und Geochemie (2016) gaben 76 an, in ihrer Arbeit keinen Beleg für ein solches Programm gefunden zu haben. Der eine, der mit Ja antwortete, verwies auf ungewöhnlich hohe Bariumwerte in der Luft einer abgelegenen Gegend; ein einzelner auffälliger Messwert belegt aber noch kein Sprühprogramm. Die von Gläubigen angeführten Messwerte ließen sich nach Einschätzung der großen Mehrheit der Befragten durch gewöhnliche Kondensstreifen-Chemie, natürliche Hintergrundkonzentrationen oder methodische Schwächen der Probenahme erklären.`,beleg:`Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program. Environmental Research Letters 11(8), 084011. https://doi.org/10.1088/1748-9326/11/8/084011. Berichtigung (betrifft die Teilnehmerzahl einer Einzelfrage, nicht die 77/76): Environmental Research Letters 11(12), 129501.`,buch:`Landkarte der Realität, Buch 1, Band II, Logbuch des Gärtners (Ende der Schmiede) und Buch 2, Werkstück C.5.3 (Atmosphärenphysik)`,familie:`verschwoerung-pruefen`,fertigkeit:`F1`,stufe:2,kurz:`In einer Befragung von 77 Fachleuten der Atmosphären- und Geochemie (2016) fanden 76 keinen Beleg für ein solches Programm. Die angeführten Messwerte lassen sich nach Einschätzung der großen Mehrheit durch gewöhnliche Ursachen oder Probenahmefehler erklären.`,prueffrage:`Welche Fachleute sollen die Belege gefunden haben, und wo haben sie ihre Messungen veröffentlicht?`,quellen:[{typ:`doi`,kurz:`Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program. Environmental Research Letters 11(8), 084011`,oeffentlich:!0,doi:`10.1088/1748-9326/11/8/084011`,url:`https://iopscience.iop.org/article/10.1088/1748-9326/11/8/084011`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Shearer, C. u. a. (2016): Corrigendum. Environmental Research Letters 11(12), 129501`,oeffentlich:!1}]},{id:`m-forer`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Forers Studierende hielten ein „persönliches“ Profil, das für alle gleich war, für sehr treffend.`,antwort:`wahr`,erklaerung:`Forer gab seinen Studierenden angeblich individuelle Persönlichkeitsprofile, in Wahrheit war der Text für alle gleich. Im Mittel bewerteten sie ihn mit 4,26 auf einer Skala von 0 bis 5. Der Name „Barnum-Effekt“ stammt übrigens nicht von Barnum, sondern von Paul Meehl (1956).`,beleg:`Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44, S. 118–123.`,buch:`Landkarte der Realität, Buch 2, Werkstück B.10 (Der Barnum-Effekt)`,familie:`passt-auf-jeden`,fertigkeit:`F2`,stufe:2,kurz:`Forer gab allen Studierenden denselben Text als angeblich persönliches Profil; im Mittel bewerteten sie ihn mit 4,26 auf einer Skala von 0 bis 5. Den Namen „Barnum-Effekt“ prägte später Paul Meehl (1956).`,prueffrage:`Wie wurde in Forers Versuch gemessen, wie treffend die Studierenden ihr Profil fanden?`,quellen:[{typ:`url`,kurz:`Carroll, R. T.: Forer effect. The Skeptic's Dictionary (skepdic.com)`,oeffentlich:!0,url:`https://skepdic.com/forer.html`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Forer, B. R. (1949): The Fallacy of Personal Validation: A Classroom Demonstration of Gullibility. Journal of Abnormal and Social Psychology 44(1), S. 118–123`,oeffentlich:!1,doi:`10.1037/h0059240`}]},{id:`m-rauchen`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Raucher sterben im Durchschnitt rund zehn Jahre früher als Nichtraucher.`,antwort:`wahr`,erklaerung:`Eine britische Langzeitstudie beobachtete über 50 Jahre mehr als 34.000 Ärzte: Männer, die ein Leben lang Zigaretten rauchten, starben im Durchschnitt rund zehn Jahre früher als lebenslange Nichtraucher. Weitere Studien aus aller Welt stützen das. Es ist ein Durchschnittswert: Er sagt nichts über den einzelnen Menschen.`,beleg:`Doll, R.; Peto, R.; Boreham, J.; Sutherland, I. (2004): Mortality in relation to smoking: 50 years' observations on male British doctors. BMJ 328, S. 1519. https://doi.org/10.1136/bmj.38142.554479.AE`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.2.6 (Die Hierarchie der Evidenz)`,familie:`befund-reichweite`,fertigkeit:`F1`,stufe:2,kurz:`Eine britische Studie, die mehr als 34.000 Ärzte 50 Jahre lang beobachtete, fand: Männer, die lebenslang Zigaretten rauchten, starben im Durchschnitt rund zehn Jahre früher als lebenslange Nichtraucher. Über den Einzelnen sagt das nichts.`,prueffrage:`Welche Langzeitstudie liegt der Zahl zugrunde, und wer genau wurde darin mit wem verglichen?`,quellen:[{typ:`doi`,kurz:`Doll, R.; Peto, R.; Boreham, J.; Sutherland, I. (2004): Mortality in relation to smoking: 50 years' observations on male British doctors. BMJ 328(7455), S. 1519 (PMID 15213107, PMCID PMC437139)`,oeffentlich:!0,doi:`10.1136/bmj.38142.554479.AE`,abruf:`2026-10-12`}]},{id:`m-mmr-autismus`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Die Masern-Mumps-Röteln-Impfung verursacht Autismus.`,antwort:`falsch`,erklaerung:`Eine dänische Studie mit 657.461 Kindern fand keinen Zusammenhang zwischen der Impfung und Autismus. Auch weitere große, unabhängige Studien mit Hunderttausenden Kindern stützen die Behauptung nicht.`,beleg:`Hviid, A.; Hansen, J. V.; Frisch, M.; Melbye, M. (2019): Measles, Mumps, Rubella Vaccination and Autism: A Nationwide Cohort Study. Annals of Internal Medicine 170(8), S. 513–520. https://doi.org/10.7326/M18-2101`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4 (Die Architektur des wissenschaftlichen Konsenses)`,familie:`evidenz-gewichten`,fertigkeit:`F1`,stufe:1,kurz:`Eine dänische Studie mit 657.461 Kindern fand keinen Zusammenhang zwischen der Masern-Mumps-Röteln-Impfung und Autismus; auch weitere große, unabhängige Studien stützen die Behauptung nicht.`,prueffrage:`Wie häufig ist Autismus bei geimpften Kindern im Vergleich zu ungeimpften, wenn man große Gruppen betrachtet?`,quellen:[{typ:`doi`,kurz:`Hviid, A.; Hansen, J. V.; Frisch, M.; Melbye, M. (2019): Measles, Mumps, Rubella Vaccination and Autism: A Nationwide Cohort Study. Annals of Internal Medicine 170(8), S. 513–520 (PMID 30831578)`,oeffentlich:!0,doi:`10.7326/M18-2101`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Taylor, L. E.; Swerdfeger, A. L.; Eslick, G. D. (2014): Vaccines are not associated with autism: an evidence-based meta-analysis of case-control and cohort studies. Vaccine 32(29), S. 3623–3629 (PMID 24814559)`,oeffentlich:!0,doi:`10.1016/j.vaccine.2014.04.085`,abruf:`2026-10-12`}]},{id:`m-lancet-rueckzug`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Die Studie von 1998, die die Masern-Mumps-Röteln-Impfung mit Autismus in Verbindung brachte, wurde von der Fachzeitschrift zurückgezogen.`,antwort:`wahr`,erklaerung:`The Lancet zog die Arbeit 2010 vollständig zurück. Sie stützte sich auf nur zwölf Kinder und hatte keine Kontrollgruppe. Dass ein Rückzug passiert, ist das Korrektiv der Wissenschaft: Eine fehlerhafte Studie bleibt nicht stehen, wenn Prüfungen den Mangel zeigen.`,beleg:`The Editors of The Lancet (2010): Retraction – Ileal-lymphoid-nodular hyperplasia, non-specific colitis, and pervasive developmental disorder in children. The Lancet 375(9713), S. 445. https://doi.org/10.1016/S0140-6736(10)60175-4`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4 (Die Architektur des wissenschaftlichen Konsenses)`,familie:`evidenz-gewichten`,fertigkeit:`F1`,stufe:2,kurz:`The Lancet zog die Studie 2010 vollständig zurück. Sie beruhte auf nur zwölf Kindern ohne Kontrollgruppe; dass fehlerhafte Arbeiten zurückgezogen werden, gehört zum Korrektiv der Wissenschaft.`,prueffrage:`Was steht heute bei dieser Studie auf der Website der Zeitschrift, und gibt es dort einen offiziellen Vermerk?`,quellen:[{typ:`doi`,kurz:`Rao, T. S. S.; Andrade, C. (2011): The MMR vaccine and autism: Sensation, refutation, retraction, and fraud. Indian Journal of Psychiatry 53(2), S. 95–96 (PMCID PMC3136032)`,oeffentlich:!0,doi:`10.4103/0019-5545.82529`,abruf:`2026-10-12`},{typ:`doi`,kurz:`The Editors of The Lancet (2010): Retraction – Ileal-lymphoid-nodular hyperplasia, non-specific colitis, and pervasive developmental disorder in children. The Lancet 375(9713), S. 445`,oeffentlich:!1,doi:`10.1016/S0140-6736(10)60175-4`}]},{id:`m-helicobacter`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Weltweit werden die meisten Magengeschwüre nicht durch Stress verursacht, sondern durch ein Bakterium.`,antwort:`wahr`,erklaerung:`Zwei australische Ärzte vertraten das in den 1980er-Jahren gegen die damalige Lehrmeinung. Sie lieferten testbare Vorhersagen und Ergebnisse, die andere wiederholen konnten. Die Antibiotika-Behandlung wurde Standard, 2005 gab es den Nobelpreis für Medizin. Wo das Bakterium seltener geworden ist, geht heute ein wachsender Anteil der Geschwüre auf Schmerzmittel wie Ibuprofen oder Acetylsalicylsäure zurück. Der Fall zeigt, dass Konsens sich ändern darf, wenn die Belege es verlangen.`,beleg:`Marshall, B. J.; Warren, J. R. (1984): Unidentified Curved Bacilli in the Stomach of Patients with Gastritis and Peptic Ulceration. The Lancet 323(8390), S. 1311–1315. https://doi.org/10.1016/S0140-6736(84)91816-6. Nobelpreis für Physiologie oder Medizin 2005: https://www.nobelprize.org/prizes/medicine/2005/summary/`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4 (Die Architektur des wissenschaftlichen Konsenses)`,familie:`ablehnung-ist-kein-beleg`,fertigkeit:`F2`,stufe:3,kurz:`Dass ein Bakterium weltweit die meisten Magengeschwüre verursacht, zeigten zwei australische Ärzte in den 1980er-Jahren gegen die damalige Lehrmeinung mit wiederholbaren Belegen; die Antibiotika-Behandlung wurde Standard, 2005 folgte der Nobelpreis.`,prueffrage:`Welche Vorhersage macht die Behauptung, die sich mit einer gezielten Behandlung überprüfen ließe?`,quellen:[{typ:`url`,kurz:`Nobel Assembly at Karolinska Institutet (2005): The Nobel Prize in Physiology or Medicine 2005 – Press release`,oeffentlich:!0,url:`https://www.nobelprize.org/prizes/medicine/2005/press-release/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Marshall, B. J.; Warren, J. R. (1984): Unidentified Curved Bacilli in the Stomach of Patients with Gastritis and Peptic Ulceration. The Lancet 323(8390), 1311–1315`,oeffentlich:!1,doi:`10.1016/S0140-6736(84)91816-6`}]},{id:`m-semmelweis-waschung`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Die Händewaschung mit Chlorlösung senkte 1847 die Sterblichkeit im Kindbett auf der Wiener Ärzteklinik deutlich.`,antwort:`wahr`,erklaerung:`Nach Einführung der Chlorwaschungen Mitte Mai 1847 (zuerst mit Chlorwasser, nach einiger Zeit mit dem billigeren Chlorkalk) fiel die monatliche Sterblichkeit der Ärzteklinik von rund 18 % im April auf rund 1 bis 5 % von Juni bis Dezember. Dass der Befund trotzdem nicht sofort überzeugte, lag auch daran, dass Ignaz Semmelweis seine ausführliche Darstellung erst 1861 veröffentlichte und keine anerkannte Erklärung hatte.`,beleg:`Semmelweis, I. P. (1861): Die Aetiologie, der Begriff und die Prophylaxis des Kindbettfiebers. Pest, Wien, Leipzig: Hartleben. Auswertung der Tabellen: Loudon, I. (2013): Ignaz Phillip Semmelweis' studies of death in childbirth. Journal of the Royal Society of Medicine 106(11), S. 461–463. https://doi.org/10.1177/0141076813507844`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4 (Die Architektur des wissenschaftlichen Konsenses)`,familie:`lehrgeschichte-pruefen`,fertigkeit:`F1`,stufe:2,kurz:`Nach Einführung der Chlorwaschungen Mitte Mai 1847 fiel die monatliche Sterblichkeit der Wiener Ärzteklinik von rund 18 % im April auf rund 1 bis 5 % von Juni bis Dezember. Überzeugt hat der Befund trotzdem nicht sofort.`,prueffrage:`Gibt es Monatszahlen zur Sterblichkeit vor und nach der Einführung, und wer hat sie aufgezeichnet?`,quellen:[{typ:`url`,kurz:`Semmelweis, I. P. (1861): Die Aetiologie, der Begriff und die Prophylaxis des Kindbettfiebers. Pest, Wien, Leipzig: Hartleben (Digitalisat Deutsches Textarchiv)`,oeffentlich:!0,url:`https://www.deutschestextarchiv.de/book/view/semmelweis_kindbettfieber_1861?p=67`,seite:`16, 55–56`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Loudon, I. (2013): Ignaz Phillip Semmelweis' studies of death in childbirth. Journal of the Royal Society of Medicine 106(11), 461–463`,oeffentlich:!0,doi:`10.1177/0141076813507844`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC3807776/`,abruf:`2026-10-12`}]},{id:`m-erdalter`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Die Erde ist rund 4,5 Milliarden Jahre alt.`,antwort:`wahr`,erklaerung:`Radiometrische Datierung (etwa über den Zerfall von Uran zu Blei) führt bei Meteoriten, die aus der Entstehungszeit des Sonnensystems stammen, übereinstimmend auf etwa 4,54 Milliarden Jahre; die ältesten Gesteine und Minerale der Erde sind nur wenig jünger. Der Zerfall radioaktiver Isotope läuft konstant und vorhersagbar, deshalb lässt sich damit das absolute Alter von Gesteinen bestimmen.`,beleg:`Dalrymple, G. B. (2001): The age of the Earth in the twentieth century: a problem (mostly) solved. Geological Society, London, Special Publications 190, S. 205–221. https://doi.org/10.1144/GSL.SP.2001.190.01.14`,buch:`Landkarte der Realität, Buch 2, Werkstück C.1.5 (Tiefenzeit & Geologie)`,familie:`groessenordnung-schaetzen`,fertigkeit:`F4`,stufe:1,kurz:`Radiometrische Datierung, etwa über den Zerfall von Uran zu Blei, führt auf etwa 4,54 Milliarden Jahre. Weil radioaktive Isotope konstant und vorhersagbar zerfallen, lässt sich damit das absolute Alter von Gesteinen bestimmen.`,prueffrage:`Mit welchem Verfahren lässt sich das Alter von Gestein messen, und kommen unabhängige Messungen auf denselben Wert?`,quellen:[{typ:`url`,kurz:`U.S. Geological Survey: Age of the Earth (Geologic Time)`,oeffentlich:!0,url:`https://pubs.usgs.gov/gip/geotime/age.html`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Dalrymple, G. B. (2001): The age of the Earth in the twentieth century: a problem (mostly) solved. Geological Society, London, Special Publications 190, 205–221`,oeffentlich:!1,doi:`10.1144/GSL.SP.2001.190.01.14`}]},{id:`m-pareidolie`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Wir sehen Gesichter auch in Dingen, die keine sind, etwa in einem Toast.`,antwort:`wahr`,erklaerung:`Pareidolie nennt man das Erkennen bekannter Muster, oft Gesichter, in vagen Reizen. Die zitierte Studie zeigt, dass wir Gesichter selbst im Rauschen sehen, wenn wir eines erwarten. Das Bild entsteht im Kopf des Betrachters, nicht auf dem Toast. Ein Muster zu sehen heißt nicht, dass etwas Bedeutsames dahintersteckt.`,beleg:`Liu, J. u. a. (2014): Seeing Jesus in toast: Neural and behavioral correlates of face pareidolia. Cortex 53, S. 60–77. https://doi.org/10.1016/j.cortex.2014.01.013`,buch:`Landkarte der Realität, Buch 2, Werkstück B.9 (Apophenie)`,familie:`muster-im-zufall`,fertigkeit:`F4`,stufe:1,kurz:`Pareidolie heißt das Erkennen bekannter Muster, oft Gesichter, in vagen Reizen; wer ein Gesicht erwartet, sieht es sogar im Rauschen. Das Bild entsteht im Kopf, und ein gesehenes Muster heißt nicht, dass etwas Bedeutsames dahintersteckt.`,prueffrage:`Wie ließe sich im Versuch prüfen, ob Menschen Gesichter auch dort sehen, wo nachweislich keines abgebildet ist?`,quellen:[{typ:`doi`,kurz:`Liu, J. u. a. (2014): Seeing Jesus in toast: Neural and behavioral correlates of face pareidolia. Cortex 53, 60–77`,oeffentlich:!0,doi:`10.1016/j.cortex.2014.01.013`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC3980010/`,abruf:`2026-10-12`}]},{id:`m-replikation`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Als 100 Studien der Psychologie wiederholt wurden, ließ sich nur gut ein Drittel der Ergebnisse bestätigen.`,antwort:`wahr`,erklaerung:`97 der 100 Originalstudien hatten ein signifikantes Ergebnis; in der Wiederholung waren davon nur 35 (36 %) erneut signifikant. Nach anderen Kriterien lag die Quote bei 39 % bzw. 47 %. Die Deutung ist umstritten, und Kritiker halten die Quote wegen abweichender Verfahren für unterschätzt. Entdeckt hat es die Wissenschaft selbst, mit ihren eigenen Werkzeugen. Es heißt nicht, dass die Psychologie wertlos ist, sondern dass einzelne Studien keine Beweise sind.`,beleg:`Open Science Collaboration (2015): Estimating the Reproducibility of Psychological Science. Science 349(6251), aac4716. https://doi.org/10.1126/science.aac4716`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.4 (Die Architektur des wissenschaftlichen Konsenses)`,familie:`wiederholung-abwarten`,fertigkeit:`F1`,stufe:3,kurz:`Von 97 ursprünglich signifikanten Ergebnissen waren in der Wiederholung nur 35 (36 %) erneut signifikant, nach anderen Kriterien 39 % bzw. 47 %. Die Deutung ist umstritten; es zeigt vor allem, dass einzelne Studien keine Beweise sind.`,prueffrage:`Nach welchem Kriterium galt ein Ergebnis als bestätigt, und wer hat die Wiederholungen durchgeführt?`,quellen:[{typ:`doi`,kurz:`Open Science Collaboration (2015): Estimating the Reproducibility of Psychological Science. Science 349(6251), aac4716`,oeffentlich:!0,doi:`10.1126/science.aac4716`,url:`https://pubmed.ncbi.nlm.nih.gov/26315443/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Gilbert, D. T.; King, G.; Pettigrew, S.; Wilson, T. D. (2016): Comment on „Estimating the reproducibility of psychological science“. Science 351(6277), 1037`,oeffentlich:!1,doi:`10.1126/science.aad7243`}]},{id:`m-dunning-kruger`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Der Dunning-Kruger-Effekt ist bewiesen: Je weniger jemand kann, desto mehr überschätzt er sich.`,antwort:`differenziert`,erklaerung:`Kruger und Dunning fanden 1999, dass die Schwächsten ihre Leistung am stärksten überschätzten. Die bekannte Kurve mit „Gipfel der Ahnungslosigkeit“ stammt nicht aus der Studie: Sie verglich vier Kompetenzgruppen, keinen Zeitverlauf. Mehrere Fachartikel halten einen erheblichen Teil des gemessenen Musters für ein statistisches Artefakt (Regression zur Mitte, Grenzen der Bewertungsskala). Wie groß der Effekt wirklich ist, wird diskutiert.`,beleg:`Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), S. 1121–1134. Nuhfer, E. u. a. (2017): How Random Noise and a Graphical Convention Subverted Behavioral Scientists' Explanations of Self-Assessment Data. Numeracy 10(1), Art. 4. https://doi.org/10.5038/1936-4660.10.1.4. Gignac, G. E.; Zajenkowski, M. (2020): The Dunning-Kruger Effect Is (Mostly) a Statistical Artefact. Intelligence 80, 101449. https://doi.org/10.1016/j.intell.2020.101449`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.7.2 (Der Dunning-Kruger-Effekt)`,familie:`befund-reichweite`,fertigkeit:`F1`,stufe:4,kurz:`Kruger und Dunning fanden 1999, dass die Schwächsten sich am stärksten überschätzten; die bekannte Kurve stammt aber nicht aus der Studie. Mehrere Fachartikel halten einen erheblichen Teil des Musters für ein statistisches Artefakt.`,prueffrage:`Wer hat das Muster mit welcher Methode gemessen, und wurde die Auswertung von anderen nachgerechnet?`,quellen:[{typ:`doi`,kurz:`Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134`,oeffentlich:!0,doi:`10.1037/0022-3514.77.6.1121`,url:`https://pubmed.ncbi.nlm.nih.gov/10626367/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Nuhfer, E. u. a. (2017): How Random Noise and a Graphical Convention Subverted Behavioral Scientists' Explanations of Self-Assessment Data. Numeracy 10(1), Art. 4`,oeffentlich:!0,doi:`10.5038/1936-4660.10.1.4`,url:`https://digitalcommons.usf.edu/numeracy/vol10/iss1/art4/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Gignac, G. E.; Zajenkowski, M. (2020): The Dunning-Kruger effect is (mostly) a statistical artefact. Intelligence 80, 101449`,oeffentlich:!1,doi:`10.1016/j.intell.2020.101449`}]},{id:`m-milgram`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Das Milgram-Experiment zeigt, dass die meisten Menschen blind jedem Befehl einer Autorität gehorchen.`,antwort:`differenziert`,erklaerung:`Bei der bekanntesten Anordnung gingen 65 % bis zum Ende. In Milgrams eigenen Varianten schwankte die Quote aber zwischen null und über 90 %, je nachdem, ob der Versuchsleiter im Raum war, ob ein zweiter „Lehrer“ sich weigerte oder ob das Opfer sichtbar war. Die Deutung als „blinder“ Gehorsam ist umstritten: Nachstellungen mit harmloser Aufgabe deuten eher auf Menschen, die einem Forschungsprojekt helfen wollten. Ganz geklärt ist das nicht; in einer polnischen Wiederholung von 2025 gehorchten die Teilnehmer fast ebenso oft, als der Versuch bloß einer Werbeagentur dienen sollte.`,beleg:`Milgram, S. (1974): Obedience to Authority: An Experimental View. New York: Harper & Row. Haslam, S. A.; Reicher, S. D.; Birney, M. E. (2014): Nothing by Mere Authority: Evidence that in an Experimental Analogue of the Milgram Paradigm Participants Are Motivated Not by Orders but by Appeals to Science. Journal of Social Issues 70(3), S. 473–488. https://doi.org/10.1111/josi.12072. Grzyb, T.; Dolinski, D.; Sudoł-Malisz, M.; Kulik, G.; Mielczarek, Ł. (2025): Doubting the power of prestige: obedience to authority beyond institutional and research justifications. Scientific Reports 15, 24911. https://doi.org/10.1038/s41598-025-10331-4`,buch:`Landkarte der Realität, Buch 1, Band III, Sektion III.3.2 (Der Mann im grauen Kittel) und Buch 2, Werkstück E.2.2 (Autorität & Gehorsam)`,familie:`befund-reichweite`,fertigkeit:`F1`,stufe:3,kurz:`In der bekanntesten Anordnung gingen 65 % bis zum Ende, in Milgrams eigenen Varianten schwankte die Quote zwischen null und über 90 %. Ob das „blinden“ Gehorsam zeigt oder den Wunsch, der Forschung zu helfen, ist umstritten.`,prueffrage:`Unter welchen Bedingungen wurde gemessen, und wie wurde „Gehorsam“ im Versuch genau erfasst?`,quellen:[{typ:`doi`,kurz:`Grzyb, T. u. a. (2025): Doubting the power of prestige: obedience to authority beyond institutional and research justifications. Scientific Reports 15, 24911`,oeffentlich:!0,doi:`10.1038/s41598-025-10331-4`,abruf:`2026-10-12`},{typ:`url`,kurz:`Haslam, S. A.; Reicher, S. D.; Birney, M. E. (2014): Nothing by Mere Authority. Journal of Social Issues 70(3), 473–488 (Abstract, Forschungsportal University of St Andrews)`,oeffentlich:!0,doi:`10.1111/josi.12072`,url:`https://research-portal.st-andrews.ac.uk/en/publications/nothing-by-mere-authority-evidence-that-in-an-experimental-analog/`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Milgram, S. (1974): Obedience to Authority: An Experimental View. New York: Harper & Row`,oeffentlich:!1}]},{id:`m-placebo`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Placebos können bei jeder Krankheit helfen, wenn man nur fest genug daran glaubt.`,antwort:`differenziert`,erklaerung:`Placebos wirken am deutlichsten auf Beschwerden, die Patienten selbst einschätzen, etwa Schmerz oder Übelkeit. Einen Tumor schrumpfen oder einen Knochenbruch heilen können sie nicht: In den Placebogruppen von Krebsstudien sprach der Tumor nur bei 2,7 % der Patienten an, was die Autoren eher auf Messfehler zurückführen. Auch die berühmte Zahl aus den 1950er-Jahren, ein Drittel der Patienten spreche allein auf ein Placebo an, gilt als deutlich zu hoch: Sie vermischte den Placebo-Effekt mit dem natürlichen Krankheitsverlauf.`,beleg:`Hróbjartsson, A.; Gøtzsche, P. C. (2010): Placebo Interventions for All Clinical Conditions. Cochrane Database of Systematic Reviews (1), CD003974. https://doi.org/10.1002/14651858.CD003974.pub3. Chvetzoff, G.; Tannock, I. F. (2003): Placebo Effects in Oncology. Journal of the National Cancer Institute 95(1), S. 19–29. https://doi.org/10.1093/jnci/95.1.19. Kienle, G. S.; Kiene, H. (1997): The Powerful Placebo Effect: Fact or Fiction? Journal of Clinical Epidemiology 50(12), S. 1311–1318. https://doi.org/10.1016/S0895-4356(97)00203-5`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.3.2 (Der Erwartungs-Effekt)`,familie:`fair-testen`,fertigkeit:`F1`,stufe:2,kurz:`Placebos wirken am deutlichsten auf selbst eingeschätzte Beschwerden wie Schmerz oder Übelkeit. Tumore schrumpfen oder Knochenbrüche heilen können sie nicht: In Placebogruppen von Krebsstudien sprach der Tumor nur bei 2,7 % an.`,prueffrage:`Bei welchen Beschwerden wurde die Wirkung gemessen, und wie wurde sie vom natürlichen Krankheitsverlauf getrennt?`,quellen:[{typ:`doi`,kurz:`Hróbjartsson, A.; Gøtzsche, P. C. (2010): Placebo interventions for all clinical conditions. Cochrane Database of Systematic Reviews (1), CD003974`,oeffentlich:!0,doi:`10.1002/14651858.CD003974.pub3`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC7156905/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Chvetzoff, G.; Tannock, I. F. (2003): Placebo Effects in Oncology. Journal of the National Cancer Institute 95(1), 19–29`,oeffentlich:!0,doi:`10.1093/jnci/95.1.19`,url:`https://pubmed.ncbi.nlm.nih.gov/12509397/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Kienle, G. S.; Kiene, H. (1997): The Powerful Placebo Effect: Fact or Fiction? Journal of Clinical Epidemiology 50(12), 1311–1318`,oeffentlich:!0,doi:`10.1016/S0895-4356(97)00203-5`,url:`https://pubmed.ncbi.nlm.nih.gov/9449934/`,abruf:`2026-10-12`}]},{id:`m-wald`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Die Geschichte der Flugzeug-Panzerung stimmt: Man verstärkte die Stellen ohne Einschusslöcher, weil abgeschossene Maschinen dort getroffen wurden.`,antwort:`differenziert`,erklaerung:`Der Kern ist echt: Die Maschinen, die zurückkamen, zeigen nur, wo ein Treffer überlebbar war. Die Daten der Abgeschossenen fehlen, und das verkehrt den naiven Schluss ins Gegenteil (Überlebensfehler). Die zugespitzte Fassung „Motoren und Cockpit panzern“ ist aber eine spätere Zuspitzung: Die erhaltenen Memoranden von Abraham Wald sind reine statistische Analysen ohne ausdrückliche Empfehlung dieser Art.`,beleg:`Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), S. 259–267. https://doi.org/10.1080/01621459.1984.10478038`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.8.1 (Die Waffe der Definition)`,familie:`fehlende-faelle-suchen`,fertigkeit:`F2`,stufe:3,kurz:`Der Kern stimmt: Zurückgekehrte Flugzeuge zeigen nur, wo Treffer überlebbar waren, die Abgeschossenen fehlen in den Daten. Die zugespitzte Empfehlung, Motoren und Cockpit zu panzern, steht so aber nicht in Abraham Walds erhaltenen Memoranden.`,prueffrage:`Welche Maschinen tauchen in den ausgewerteten Daten gar nicht auf, und welche Originaldokumente gibt es zu der Geschichte?`,quellen:[{typ:`url`,kurz:`Casselman, B. (2016): The Legend of Abraham Wald. American Mathematical Society, Feature Column, Juni 2016`,oeffentlich:!0,url:`https://www.ams.org/publicoutreach/feature-column/fc-2016-06`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267`,oeffentlich:!1,doi:`10.1080/01621459.1984.10478038`}]},{id:`m-priming`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Priming beeinflusst unser Verhalten unbemerkt: Wer Wörter rund ums Alter liest, geht danach langsamer.`,antwort:`differenziert`,erklaerung:`Semantisches Priming (ein Wort erleichtert verwandte Wörter) gehört zu den robustesten, am häufigsten replizierten Befunden der kognitiven Psychologie. Das umstrittenere „soziale“ Verhaltens-Priming, etwa langsameres Gehen nach alterstypischen Wörtern, ließ sich in einer sorgfältigen Wiederholung mit automatischer Zeitmessung nicht bestätigen; ein Effekt trat nur auf, wenn die Versuchsleiter ihn erwarteten.`,beleg:`Meyer, D. E.; Schvaneveldt, R. W. (1971): Facilitation in Recognizing Pairs of Words. Journal of Experimental Psychology 90(2), S. 227–234. https://doi.org/10.1037/h0031564. Bargh, J. A.; Chen, M.; Burrows, L. (1996): Automaticity of Social Behavior. Journal of Personality and Social Psychology 71(2), S. 230–244. Doyen, S.; Klein, O.; Pichon, C.-L.; Cleeremans, A. (2012): Behavioral Priming: It’s All in the Mind, but Whose Mind? PLOS ONE 7(1), e29081. https://doi.org/10.1371/journal.pone.0029081`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.7 (Denkfehler-Enzyklopädie)`,familie:`wiederholung-abwarten`,fertigkeit:`F1`,stufe:3,kurz:`Dass ein Wort das Erkennen verwandter Wörter erleichtert, ist gut belegt. Dass Wörter rund ums Alter Menschen langsamer gehen lassen, bestätigte eine sorgfältige Wiederholung mit automatischer Zeitmessung nicht; ein Effekt trat nur auf, wenn die Versuchsleiter ihn erwarteten.`,prueffrage:`Welche Art von Priming ist gemeint, und haben unabhängige Teams den Effekt auf die Gehgeschwindigkeit nachgemessen?`,quellen:[{typ:`doi`,kurz:`Doyen, S.; Klein, O.; Pichon, C.-L.; Cleeremans, A. (2012): Behavioral Priming: It's All in the Mind, but Whose Mind? PLOS ONE 7(1), e29081`,oeffentlich:!0,doi:`10.1371/journal.pone.0029081`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Meyer, D. E.; Schvaneveldt, R. W. (1971): Facilitation in Recognizing Pairs of Words. Journal of Experimental Psychology 90(2), 227–234`,oeffentlich:!1,doi:`10.1037/h0031564`},{typ:`doi`,kurz:`Bargh, J. A.; Chen, M.; Burrows, L. (1996): Automaticity of Social Behavior. Journal of Personality and Social Psychology 71(2), 230–244`,oeffentlich:!1,doi:`10.1037/0022-3514.71.2.230`}]},{id:`m-muenzwurf`,typ:`mythos`,status:`entwurf`,thema:`Geld und Zahlen`,aussage:`Eine geworfene Münze landet genau zu 50 % auf Kopf und zu 50 % auf Zahl.`,antwort:`differenziert`,erklaerung:`Praktisch stimmt es, und vorherige Würfe spielen keine Rolle: Die Münze hat kein Gedächtnis. Ganz genau landet sie in einem Großexperiment mit 350.757 Würfen aber in etwa 50,8 % der Fälle auf der Seite, mit der sie nach oben gestartet ist. Ein kleiner, messbarer Unterschied, der den Spielerfehlschluss nicht rechtfertigt.`,beleg:`Bartoš, F. u. a. (2025): Fair Coins Tend to Land on the Same Side They Started: Evidence from 350,757 Flips. Journal of the American Statistical Association 120(552), S. 2118–2127. https://doi.org/10.1080/01621459.2025.2516210`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.2 und Buch 2, Werkstück B.30 (Der Spielerfehlschluss)`,familie:`zufall-ohne-gedaechtnis`,fertigkeit:`F4`,stufe:2,kurz:`Praktisch stimmt es, und frühere Würfe spielen keine Rolle, denn die Münze hat kein Gedächtnis. Ganz genau stimmt es nicht: In einem Großexperiment landete sie in etwa 50,8 % der Fälle auf der Seite, die beim Start oben lag.`,prueffrage:`Wer hat das mit sehr vielen echten Würfen nachgezählt, und welche Bedingungen des Wurfs wurden dabei festgehalten?`,quellen:[{typ:`doi`,kurz:`Bartoš, F. u. a. (2025): Fair Coins Tend to Land on the Same Side They Started: Evidence from 350,757 Flips. Journal of the American Statistical Association 120(552), 2118–2127`,oeffentlich:!0,doi:`10.1080/01621459.2025.2516210`,url:`https://arxiv.org/abs/2310.04153`,abruf:`2026-10-12`}]},{id:`m-algorithmus-radikal`,typ:`mythos`,status:`entwurf`,thema:`Netz und Medien`,aussage:`Soziale Netzwerke radikalisieren Menschen allein durch ihre Algorithmen.`,antwort:`differenziert`,erklaerung:`Dass Empörung Reichweite bringt, ist gut belegt. Dass der Algorithmus allein radikalisiert, nicht: In großen Feldexperimenten mit Facebook- und Instagram-Nutzern im US-Wahlkampf 2020 senkte ein chronologischer Feed die Nutzungszeit, veränderte aber Polarisierung und politische Einstellungen innerhalb von drei Monaten nicht messbar. Diese Studien liefen drei Monate, in Zusammenarbeit mit dem Konzern und mit Sondermaßnahmen der Plattform; Langzeiteffekte sind nicht erfasst. Ein unabhängiges Experiment auf X (2023, rund 5.000 Nutzer, sieben Wochen) fand ebenfalls keine stärkere Polarisierung, aber eine leichte Verschiebung in einzelnen Sachfragen in konservative Richtung. Der Algorithmus ist also eher ein Verstärker der eigenen Neigungen als ein Puppenspieler.`,beleg:`Guess, A. M. u. a. (2023): How Do Social Media Feed Algorithms Affect Attitudes and Behavior in an Election Campaign? Science 381(6656), S. 398–404. https://doi.org/10.1126/science.abp9364. Nyhan, B. u. a. (2023): Like-Minded Sources on Facebook Are Prevalent but Not Polarizing. Nature 620, S. 137–144. https://doi.org/10.1038/s41586-023-06297-w. Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X’s feed algorithm. Nature 652(8109), S. 416–423. https://doi.org/10.1038/s41586-026-10098-2`,buch:`Landkarte der Realität, Buch 1, Band III, Sektion III.6.2 (Der algorithmische Brandbeschleuniger)`,familie:`monokausal-erkennen`,fertigkeit:`F2`,stufe:3,kurz:`Dass Empörung Reichweite bringt, ist gut belegt, dass Algorithmen allein radikalisieren, nicht: In Feldexperimenten änderte ein anderer Feed die Polarisierung über Wochen bis Monate nicht messbar. Langzeitfolgen sind offen; der Feed verstärkt eher vorhandene Neigungen.`,prueffrage:`Wie ließe sich die Wirkung des Algorithmus von dem trennen, was Nutzer ohnehin mitbringen, und wer hat das im Experiment versucht?`,quellen:[{typ:`doi`,kurz:`Guess, A. M. u. a. (2023): How do social media feed algorithms affect attitudes and behavior in an election campaign? Science 381(6656), 398–404`,oeffentlich:!0,doi:`10.1126/science.abp9364`,url:`https://pubmed.ncbi.nlm.nih.gov/37498999/`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Nyhan, B. u. a. (2023): Like-minded sources on Facebook are prevalent but not polarizing. Nature 620, 137–144`,oeffentlich:!0,doi:`10.1038/s41586-023-06297-w`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Gauthier, G.; Hodler, R.; Widmer, P.; Zhuravskaya, E. (2026): The political effects of X's feed algorithm. Nature 652(8109), 416–423`,oeffentlich:!0,doi:`10.1038/s41586-026-10098-2`,abruf:`2026-10-12`}]},{id:`m-prebunking`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Ein kurzes Training vorab macht Menschen widerstandsfähiger gegen Desinformation (Prebunking).`,antwort:`differenziert`,erklaerung:`In Studien mit Spielen und Kurzvideos erkannten Teilnehmende Manipulationstechniken danach messbar besser. Die Effekte sind aber klein bis mittel und klingen ohne Auffrischung nach Wochen ab; im Feldversuch auf YouTube stieg die Erkennung nur um rund fünf Prozent. Prebunking ist ein Baustein, kein Impfstoff.`,beleg:`Roozenbeek, J.; van der Linden, S.; Goldberg, B.; Rathje, S.; Lewandowsky, S. (2022): Psychological Inoculation Improves Resilience Against Misinformation on Social Media. Science Advances 8(34), eabo6254. https://doi.org/10.1126/sciadv.abo6254. Maertens, R. u. a. (2025): Psychological Booster Shots Targeting Memory Increase Long-Term Resistance Against Misinformation. Nature Communications 16, 2062. https://doi.org/10.1038/s41467-025-57205-x`,buch:`Landkarte der Realität, Buch 2, Anhang I, Checkliste 2 (FAKE-Framework)`,familie:`befund-reichweite`,fertigkeit:`F1`,stufe:2,kurz:`Kurze Spiele oder Videos helfen messbar, Manipulationstechniken zu erkennen. Die Effekte sind aber klein bis mittel und klingen ohne Auffrischung nach Wochen ab: Prebunking ist ein Baustein, kein Impfstoff.`,prueffrage:`Wie groß ist der Effekt außerhalb des Labors, und wie lange hält er an?`,quellen:[{typ:`doi`,kurz:`Roozenbeek, J. u. a. (2022): Psychological Inoculation Improves Resilience Against Misinformation on Social Media. Science Advances 8(34), eabo6254`,oeffentlich:!0,doi:`10.1126/sciadv.abo6254`,seite:`S. 5 (laut Belegregister, Verlags-PDF)`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Maertens, R. u. a. (2025): Psychological Booster Shots Targeting Memory Increase Long-Term Resistance Against Misinformation. Nature Communications 16, 2062`,oeffentlich:!0,doi:`10.1038/s41467-025-57205-x`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Lewandowsky, S.; van der Linden, S. (2021): Countering Misinformation and Fake News Through Inoculation and Prebunking. European Review of Social Psychology 32(2), S. 348–384`,oeffentlich:!1,doi:`10.1080/10463283.2021.1876983`}]},{id:`m-klimakonsens`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`99 % aller Forschenden sind sich einig, dass der Mensch das Klima erwärmt.`,antwort:`differenziert`,erklaerung:`Die Zahlen messen den Anteil der Fachliteratur, die eine menschengemachte Erwärmung bejaht, nicht den Anteil „der Forscher“. Eine Zufallsstichprobe von 3.000 aus 88.125 klimabezogenen Fachartikeln (2012–2020) ergab: 4 von 2.718 Arbeiten bestritten die menschengemachte Erwärmung, das ergibt mehr als 99 % Zustimmung. Die ältere Zahl von 97 % stammt aus einer Auswertung von 2013; die beiden Zahlen zählen unterschiedlich. Die genaue Zahl hängt also von Methode und Auswahl der Artikel ab. Die Aussage dahinter, ein sehr breiter Konsens, stimmt.`,beleg:`Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005. https://doi.org/10.1088/1748-9326/ac2966. Cook, J. u. a. (2013): Quantifying the Consensus on Anthropogenic Global Warming in the Scientific Literature. Environmental Research Letters 8(2), 024024. https://doi.org/10.1088/1748-9326/8/2/024024`,buch:`Landkarte der Realität, Buch 1, Band VI, Kalibrierungs-Ritual (Das Klima-Duell)`,familie:`zahl-zur-quelle`,fertigkeit:`F1`,stufe:3,kurz:`Ein sehr breiter Konsens besteht. Die 99 % zählen aber Fachartikel, nicht Forschende: Nur sehr wenige der ausgewerteten Arbeiten bestritten die menschengemachte Erwärmung. Die genaue Zahl hängt von Methode und Auswahl ab; eine ältere Auswertung kam auf 97 %.`,prueffrage:`Was genau wurde gezählt, um auf 99 % zu kommen, und nach welchen Regeln wurde ausgewählt?`,quellen:[{typ:`doi`,kurz:`Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005`,oeffentlich:!0,doi:`10.1088/1748-9326/ac2966`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Cook, J. u. a. (2013): Quantifying the Consensus on Anthropogenic Global Warming in the Scientific Literature. Environmental Research Letters 8(2), 024024`,oeffentlich:!0,doi:`10.1088/1748-9326/8/2/024024`,abruf:`2026-10-12`}]},{id:`m-yeti-haare`,typ:`mythos`,status:`entwurf`,thema:`Natur und Klima`,aussage:`Genanalysen von Haarproben haben gezeigt, dass Yeti und Bigfoot eine unbekannte Primatenart sind.`,antwort:`falsch`,erklaerung:`In der genetischen Untersuchung von Haarproben, die als von Yeti, Bigfoot und ähnlichen Wesen stammend eingereicht wurden, passte jede auswertbare Probe zu einer bekannten Tierart, von Bären über Pferde bis zum Menschen. Keine Probe stammte von einem unbekannten Primaten. Die vorläufige Zuordnung zweier Himalaya-Proben zu einem eiszeitlichen Eisbären gilt inzwischen als überholt (heutiger Himalaya-Braunbär). Bis heute wurde auch kein einziger Körper und kein junges Fossil eines solchen Wesens wissenschaftlich bestätigt.`,beleg:`Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proceedings of the Royal Society B 281(1789), 20140161. https://doi.org/10.1098/rspb.2014.0161. Zur Überholung der Eisbär-Zuordnung: Lan, T. u. a. (2017): Proceedings of the Royal Society B 284(1868), 20171804.`,buch:`Landkarte der Realität, Buch 2, Werkstück C.3.4 (Populationsbiologie & Ökologie)`,familie:`population-und-spuren`,fertigkeit:`F1`,stufe:1,kurz:`Bei der genetischen Untersuchung eingereichter Yeti- und Bigfoot-Haare passte jede auswertbare Probe zu einer bekannten Tierart, etwa zu Bären, Pferden oder Menschen. Von einem unbekannten Primaten stammte keine.`,prueffrage:`Wer hat die Haarproben untersucht, und mit welchen bekannten Tierarten wurden die Ergebnisse verglichen?`,quellen:[{typ:`doi`,kurz:`Sykes, B. C. u. a. (2014): Genetic Analysis of Hair Samples Attributed to Yeti, Bigfoot and Other Anomalous Primates. Proceedings of the Royal Society B 281(1789), 20140161`,oeffentlich:!0,doi:`10.1098/rspb.2014.0161`,abruf:`2026-10-12`},{typ:`doi`,kurz:`Lan, T. u. a. (2017): Evolutionary History of Enigmatic Bears in the Tibetan Plateau–Himalaya Region and the Identity of the Yeti. Proceedings of the Royal Society B 284(1868), 20171804`,oeffentlich:!0,doi:`10.1098/rspb.2017.1804`,abruf:`2026-10-12`}]},{id:`m-detox`,typ:`mythos`,status:`entwurf`,thema:`Gesundheit`,aussage:`Detox-Kuren befreien den Körper von „Schlacken“ besser als Leber und Nieren.`,antwort:`falsch`,erklaerung:`Eine Übersichtsarbeit fand keine randomisierten kontrollierten Studien zu kommerziellen Detox-Diäten beim Menschen und keine überzeugenden Belege dafür, dass solche Diäten Giftstoffe wirksamer ausscheiden als der Körper selbst. Der scheidet Fremdstoffe über Leber, Nieren, Darm, Haut und Lunge aus. Anbieter nennen selten, welche „Toxine“ sie entfernen wollen; „Schlacken“ ist ein medizinisch undefinierter Begriff.`,beleg:`Klein, A. V.; Kiat, H. (2015): Detox Diets for Toxin Elimination and Weight Management: A Critical Review of the Evidence. Journal of Human Nutrition and Dietetics 28(6), S. 675–686. https://doi.org/10.1111/jhn.12286`,buch:`Landkarte der Realität, Buch 1, Band I, Kapitel 1.10.1 (Die Fassade) und Buch 2, Werkstück G.3.1 (Toxine, Schlacken, Entgiften)`,familie:`begriff-messbar-machen`,fertigkeit:`F1`,stufe:1,kurz:`Fremdstoffe scheidet der Körper selbst über Leber, Nieren, Darm, Haut und Lunge aus. Dass Detox-Kuren das besser können, ist nicht belegt; kontrollierte Studien dazu fehlen. „Schlacken“ ist kein medizinisch definierter Begriff.`,prueffrage:`Welche Stoffe genau sollen die Kuren entfernen, und wo wurde gemessen, dass davon danach weniger im Körper ist?`,quellen:[{typ:`doi`,kurz:`Klein, A. V.; Kiat, H. (2015): Detox Diets for Toxin Elimination and Weight Management: A Critical Review of the Evidence. Journal of Human Nutrition and Dietetics 28(6), S. 675–686`,oeffentlich:!1,doi:`10.1111/jhn.12286`},{typ:`url`,kurz:`National Center for Complementary and Integrative Health (NIH): „Detoxes“ and „Cleanses“: What You Need To Know (Stand März 2025)`,oeffentlich:!0,url:`https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know`,abruf:`2026-10-12`}]},{id:`m-neuroplastizitaet`,typ:`mythos`,status:`entwurf`,thema:`Psychologie`,aussage:`Regelmäßiges Üben verändert messbar die Struktur des Gehirns.`,antwort:`differenziert`,erklaerung:`Drei Monate Jonglier-Training vergrößerten die graue Substanz in bewegungsverarbeitenden Arealen; nach Ende des Trainings bildete sich der Zuwachs teilweise zurück. Die Effekte sind klein, und ein einzelner Gedanke baut nichts um. Wie belastbar solche Messungen sind, ist umstritten: Ein kritischer Überblick hält die Evidenz für trainingsbedingte Strukturveränderungen im erwachsenen Gehirn wegen Mängeln in Design und Statistik für ernsthaft geschwächt.`,beleg:`Draganski, B. u. a. (2004): Changes in Grey Matter Induced by Training. Nature 427, S. 311–312. https://doi.org/10.1038/427311a. Thomas, C.; Baker, C. I. (2013): Teaching an Adult Brain New Tricks: A Critical Review of Evidence for Training-Dependent Structural Plasticity in Humans. NeuroImage 73, S. 225–236. https://doi.org/10.1016/j.neuroimage.2012.03.069`,buch:`Landkarte der Realität, Buch 2, Anhang V.1 (Die Geschichte der Aufklärung)`,familie:`befund-reichweite`,fertigkeit:`F1`,stufe:4,kurz:`Nach drei Monaten Jonglier-Training wuchs die graue Substanz in bewegungsverarbeitenden Arealen und bildete sich danach teils zurück. Die Effekte sind klein, und wie belastbar solche Messungen sind, ist umstritten.`,prueffrage:`Wie groß sind die gemessenen Veränderungen, wie lange halten sie, und wie zuverlässig misst die Methode so etwas?`,quellen:[{typ:`doi`,kurz:`Draganski, B. u. a. (2004): Changes in Grey Matter Induced by Training. Nature 427, S. 311–312`,oeffentlich:!1,doi:`10.1038/427311a`},{typ:`doi`,kurz:`Driemeyer, J. u. a. (2008): Changes in Gray Matter Induced by Learning – Revisited. PLoS ONE 3(7), e2669`,oeffentlich:!0,doi:`10.1371/journal.pone.0002669`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Thomas, C.; Baker, C. I. (2013): Teaching an Adult Brain New Tricks: A Critical Review of Evidence for Training-Dependent Structural Plasticity in Humans. NeuroImage 73, S. 225–236`,oeffentlich:!1,doi:`10.1016/j.neuroimage.2012.03.069`}]},{id:`m-fehlschluss-fehlschluss`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Wer eine Behauptung mit einem fehlerhaften Argument verteidigt, hat damit gezeigt, dass die Behauptung falsch ist.`,antwort:`falsch`,erklaerung:`Ein fehlerhaftes Argument stützt seine Schlussfolgerung nicht, falsch wird sie dadurch aber nicht. Wer sagt „Schau dir diesen heißen Sommer an, der Klimawandel ist real!“, verwechselt Wetter und Klima. Den Trend zeigen trotzdem Messreihen über Jahrzehnte, ganz gleich, wie schlecht ihn jemand verteidigt. Wer aus dem schlechten Argument folgert, an der Erwärmung sei nichts dran, begeht den Fehlschluss-Fehlschluss. Ein Etikett wie „Strohmann“ oder „Ad hominem“ widerlegt nichts: Prüfe, ob es passt und was für die Behauptung selbst spricht.`,beleg:`Novella, S. u. a. (2018): The Skeptics’ Guide to the Universe. New York: Grand Central, Kap. 10 (Arguments and Logical Fallacies), Abschnitt „Fallacy Fallacy“ (E-Book ohne Seitenzahlen). Walton, D. (1998): Ad Hominem Arguments. Tuscaloosa: University of Alabama Press, S. xiv–xv. Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), S. 1–24, hier S. 6.`,buch:`Landkarte der Realität, Buch 2, Cluster D, Kasten „Ein Wort zum Gebrauch der Etiketten“ am Anfang von Cluster D`,familie:`fehlschluss-macht-nichts-falsch`,fertigkeit:`F2`,stufe:2,kurz:`Ein fehlerhaftes Argument stützt seine Behauptung nicht, widerlegt sie aber auch nicht. Ob sie stimmt, entscheiden andere Belege: Ein heißer Sommer beweist keinen Klimawandel, die Messreihen über Jahrzehnte zeigen ihn trotzdem.`,prueffrage:`Womit wird sonst geprüft, ob eine Behauptung stimmt, und wie hängt das mit der Qualität ihrer Verteidigung zusammen?`,quellen:[{typ:`url`,kurz:`Curtis, G. N.: Fallacy Fallacy. The Fallacy Files`,oeffentlich:!0,url:`https://fallacyfiles.org/fallfall.html`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Novella, S. u. a. (2018): The Skeptics’ Guide to the Universe. New York: Grand Central, Kap. 10, Abschnitt „Fallacy Fallacy“ (E-Book ohne Seiten)`,oeffentlich:!1},{typ:`literatur`,kurz:`Walton, D. (1998): Ad Hominem Arguments. Tuscaloosa: University of Alabama Press`,oeffentlich:!1,seite:`S. xiv–xv`}]},{id:`m-ki-beleg`,typ:`mythos`,status:`entwurf`,thema:`Technik und KI`,aussage:`Wenn ein KI-Sprachmodell zu einer Behauptung eine Studie nennt, ist das ein Beleg.`,antwort:`falsch`,erklaerung:`Was ein Sprachmodell liefert, ist eine Liste von Kandidaten, keine Quelle. Fünf Fehler treten regelmäßig auf: Die Quelle existiert nicht, sie sagt etwas anderes, sie ist überholt, die Zusammenfassung verdreht das Ergebnis, oder das Modell stimmt zu, weil man ihm die eigene Hypothese verraten hat. Auch umgekehrt irren Modelle: In einem kleinen Test von 2025 hielt jedes der sieben geprüften Modelle mindestens eines von zehn echten Pressefotos für KI-erzeugt. Erst wenn man die Quelle außerhalb der KI öffnet, DOI oder Fundstelle prüft und die Kernaussage im Original liest, ist es ein Beleg.`,beleg:`Chandrasekar, A.; Jaźwińska, K. (2025): Why AI Models Are Bad at Verifying Photos. Columbia Journalism Review, 26.08.2025 (Test des Tow Center for Digital Journalism mit den Modellversionen vom Sommer 2025). https://www.cjr.org/tow_center/why-ai-models-are-bad-at-verifying-photos.php. Zu erfundenen Quellen vor Gericht: Mata v. Avianca, Inc., 678 F. Supp. 3d 443 (S.D.N.Y. 2023).`,buch:`Landkarte der Realität, Buch 2, Anhang VII.2, Kasten „KI-Ergebnis ≠ Beleg“`,familie:`ki-ausgabe-pruefen`,fertigkeit:`F1`,stufe:1,kurz:`Ein Sprachmodell liefert Kandidaten, keine Quellen: Genannte Studien können erfunden, überholt oder verdreht wiedergegeben sein. Zum Beleg wird eine Studie erst, wenn man sie außerhalb der KI öffnet, DOI oder Fundstelle prüft und die Kernaussage im Original liest.`,prueffrage:`Wo lässt sich die genannte Studie unabhängig vom Modell auffinden, und was steht dort im Original?`,quellen:[{typ:`url`,kurz:`Chandrasekar, A.; Jaźwińska, K. (2025): Why AI Models Are Bad at Verifying Photos. Columbia Journalism Review (Tow Center), 26.08.2025`,oeffentlich:!0,url:`https://www.cjr.org/tow_center/why-ai-models-are-bad-at-verifying-photos.php`,abruf:`2026-10-12`},{typ:`url`,kurz:`U.S. District Court S.D.N.Y. (Castel, J.) (2023): Mata v. Avianca, Inc., 22-cv-1461, Opinion and Order on Sanctions, 22.06.2023 (Dok. 54; 678 F. Supp. 3d 443), Abruf über CourtListener/RECAP`,oeffentlich:!0,url:`https://storage.courtlistener.com/recap/gov.uscourts.nysd.575368/gov.uscourts.nysd.575368.54.0.pdf`,seite:`S. 1`,abruf:`2026-10-12`}]},{id:`m-hanlon`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Hanlons Rasiermesser („Schreibe niemals der Böswilligkeit zu, was durch Dummheit hinreichend erklärt werden kann“) hat ein Robert J. Hanlon formuliert.`,antwort:`differenziert`,erklaerung:`Die Urheberschaft ist ungeklärt. Der Satz erschien 1980 unter der Überschrift „Hanlon’s Razor“ in einer Sammlung zu Murphys Gesetz, ohne Namen eines Einsenders. Dass ihn ein Robert J. Hanlon eingesandt habe, berichtet ein Rechercheur erst 2016; das Jargon File erklärte die Herkunft 1990 für unbekannt. Sinngleiche Formulierungen sind deutlich älter, etwa bei Robert A. Heinlein (1941) und H. G. Wells (1896). Der Name hat sich als Bezeichnung durchgesetzt, gesichert ist die Zuschreibung nicht.`,beleg:`Bloch, A. (1980): Murphy’s Law, Book Two: More Reasons Why Things Go Wrong! S. 52. O’Toole, G. (Quote Investigator, 30.12.2016, abgerufen 04.10.2026). Heinlein, R. A. (1941): Logic of Empire (Kurzgeschichte). Wells, H. G. (1896): The Wheels of Chance.`,buch:`Landkarte der Realität, Buch 2, Werkstück A.1.2 (Hanlons Rasiermesser)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:4,kurz:`Der Satz erschien 1980 als „Hanlon’s Razor“ in einer Sammlung zu Murphys Gesetz, ohne Namen eines Einsenders. Dass ihn ein Robert J. Hanlon einsandte, wurde erst 2016 berichtet; ähnliche Gedanken sind viel älter. Der Name ist üblich, die Urheberschaft ungesichert.`,prueffrage:`Wo ist der Satz zuerst gedruckt erschienen, und wer hat die Zuschreibung an Hanlon wann zum ersten Mal belegt?`,quellen:[{typ:`literatur`,kurz:`Bloch, A. (1980): Murphy’s Law, Book Two: More Reasons Why Things Go Wrong! Los Angeles: Price/Stern/Sloan`,oeffentlich:!1,seite:`S. 52`},{typ:`url`,kurz:`O’Toole, G. (2016): Never Attribute to Malice That Which Is Adequately Explained by Stupidity. Quote Investigator, 30.12.2016`,oeffentlich:!0,url:`https://quoteinvestigator.com/2016/12/30/not-malice/`,abruf:`2026-10-12`},{typ:`url`,kurz:`Wikipedia: Hanlon’s razor (Abschnitt zur Herkunft; Jargon File 1990, Heinlein 1941, Wells 1896)`,oeffentlich:!0,url:`https://en.wikipedia.org/wiki/Hanlon%27s_razor`,abruf:`2026-10-12`}]},{id:`m-hebb`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`„Neurons that fire together, wire together“ ist ein Satz von Donald Hebb.`,antwort:`falsch`,erklaerung:`Die griffige Formel ist keine Originalformulierung Donald Hebbs (1949), sondern eine spätere Zusammenfassung seines Postulats; meist wird sie der Neurowissenschaftlerin Carla Shatz zugeschrieben (1992). Hebbs eigene Fassung ist deutlich sperriger: Wenn das Axon einer Zelle A nah genug an einer Zelle B liegt und wiederholt an deren Aktivierung beteiligt ist, tritt in einer oder beiden Zellen ein Wachstums- oder Stoffwechselprozess ein, der die Effizienz von A bei der Erregung von B erhöht.`,beleg:`Hebb, D. O. (1949): The Organization of Behavior. Zur Formel: Shatz zugeschrieben, Scientific American, September 1992.`,buch:`Landkarte der Realität, Buch 2, Werkstück H.1.5 (Neuroplastizität & Konzentration)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:3,kurz:`Hebb beschrieb sein Prinzip 1949 in einer sperrigen Fassung über Zellen, die einander wiederholt erregen. Die griffige Formel ist eine spätere Zusammenfassung; meist wird sie der Neurowissenschaftlerin Carla Shatz (1992) zugeschrieben.`,prueffrage:`Wo taucht genau diese Formulierung zum ersten Mal auf, und wie lautet die entsprechende Stelle in Hebbs Buch von 1949?`,quellen:[{typ:`url`,kurz:`Liberman, M. (2016): Firing and Wiring. Language Log, 21.04.2016`,oeffentlich:!0,url:`https://languagelog.ldc.upenn.edu/nll/?p=25194`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Hebb, D. O. (1949): The Organization of Behavior. New York: Wiley`,oeffentlich:!1},{typ:`literatur`,kurz:`Shatz, C. J. (1992): The Developing Brain. Scientific American 267(3), September 1992`,oeffentlich:!1}]},{id:`m-hume-guillotine`,typ:`mythos`,status:`entwurf`,thema:`Geschichte und Wissenschaft`,aussage:`Den Namen „Humes Guillotine“ für die Kluft zwischen Sein und Sollen hat David Hume selbst geprägt.`,antwort:`falsch`,erklaerung:`Hume beschrieb die Lücke 1739/40 in seinem „Treatise of Human Nature“: Viele Moralsysteme springen unbemerkt von dem, was ist, zu dem, was sein sollte. Den Namen „Humes Guillotine“ hat er nie benutzt; er stammt aus der späteren Fachliteratur und wurde wohl von Max Black (1964) geprägt.`,beleg:`Hume, D. (1739/40): A Treatise of Human Nature, Buch III, Teil I, Abschnitt I. Black, M. (1964): The Gap Between ‚Is‘ and ‚Should‘. Philosophical Review 73(2), S. 165–181.`,buch:`Landkarte der Realität, Buch 1, Band IV, Sektion IV.2.2 (Die „Ist-Soll-Lücke“)`,familie:`zitat-am-original-pruefen`,fertigkeit:`F1`,stufe:2,kurz:`Hume beschrieb 1739/40 die Lücke zwischen dem, was ist, und dem, was sein soll. Den Namen „Humes Guillotine“ benutzte er nie; er stammt aus der späteren Fachliteratur. Die Guillotine selbst kam erst nach Humes Tod (1776) in Gebrauch.`,prueffrage:`In welchem Text taucht der Name „Humes Guillotine“ zum ersten Mal auf?`,quellen:[{typ:`url`,kurz:`Hume, D. (1739/40): A Treatise of Human Nature, Buch III, Teil I, Abschnitt I. Project Gutenberg Nr. 4705`,oeffentlich:!0,url:`https://www.gutenberg.org/cache/epub/4705/pg4705.txt`,abruf:`2026-10-12`},{typ:`literatur`,kurz:`Black, M. (1964): The Gap Between ‚Is‘ and ‚Should‘. Philosophical Review 73(2), S. 165–181`,oeffentlich:!1}]}],a={stand:n,werk:r,mythen:i};export{t as n,a as t};